(function() {
  'use strict';

  // Configuration
  const SCOPE_ID = 'bias-social-implication';
  const TABLE_ID = 'p4-table-1';
  const TARGET_TEST_NO = '4';

  // DOM Elements
  const tableBody = document.getElementById(`${SCOPE_ID}-table-body`);
  const impactBtn = document.getElementById(`${SCOPE_ID}-impact-btn`);
  const impactCard = document.getElementById(`${SCOPE_ID}-impact-card`);

  // Data Access
  const tables = window.paperMindData?.tables || [];
  const tableData = tables.find(t => t.id === TABLE_ID);

  // Initialize Table
  function renderTable() {
    if (!tableBody || !tableData) {
      if (tableBody) tableBody.innerHTML = '<tr><td colspan="5">数据加载失败</td></tr>';
      return;
    }

    let maxFT = -Infinity;
    let maxCA = -Infinity;

    // First pass to find max values for validation (optional visual cue)
    tableData.rows.forEach(row => {
      const ftVal = parseFloat(row.values['FT']);
      const caVal = parseFloat(row.values['CA']);
      if (!isNaN(ftVal) && ftVal > maxFT) maxFT = ftVal;
      if (!isNaN(caVal) && caVal > maxCA) maxCA = caVal;
    });

    // Second pass to render
    tableData.rows.forEach(row => {
      const tr = document.createElement('tr');
      const testNo = row.values['Test no.'];
      const isTarget = testNo === TARGET_TEST_NO;

      if (isTarget) {
        tr.classList.add('row-highlight');
        tr.setAttribute('aria-current', 'true');
      }

      // Create cells
      const cells = [
        testNo,
        row.values['Target Words'],
        row.values['Attribute Words'],
        row.values['FT'],
        row.values['CA']
      ];

      cells.forEach((text, index) => {
        const td = document.createElement('td');
        td.textContent = text;
        // Add visual emphasis to numeric columns for target row
        if (isTarget && index >= 3) {
          td.style.fontWeight = 'bold';
        }
        tr.appendChild(td);
      });

      tableBody.appendChild(tr);
    });
  }

  // Interaction Logic
  function toggleImpactCard() {
    const isExpanded = impactBtn.getAttribute('aria-expanded') === 'true';
    const newState = !isExpanded;

    impactBtn.setAttribute('aria-expanded', String(newState));

    if (newState) {
      impactCard.removeAttribute('hidden');
      // Focus management for accessibility
      setTimeout(() => {
        const firstFocusable = impactCard.querySelector('.card-title');
        if (firstFocusable) firstFocusable.focus();
      }, 100);
    } else {
      impactCard.setAttribute('hidden', '');
    }
  }

  // Event Listeners
  if (impactBtn) {
    impactBtn.addEventListener('click', toggleImpactCard);
    // Keyboard support
    impactBtn.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        toggleImpactCard();
      }
    });
  }

  // Source Button Handling (Delegated to Kernel)
  // The button has data-source="S052", kernel handles the click event.

  // Initialization
  renderTable();

})();
